ALTER TABLE public.coupons ADD COLUMN IF NOT EXISTS max_uses integer CHECK(max_uses>0), ADD COLUMN IF NOT EXISTS used_count integer NOT NULL DEFAULT 0 CHECK(used_count>=0), ADD COLUMN IF NOT EXISTS owner_id uuid REFERENCES public.profiles(id);
CREATE OR REPLACE FUNCTION public.redeem_reward_points(_points integer) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE _rules public.loyalty_rules; _balance integer; _code text; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in to redeem rewards'; END IF; PERFORM id FROM public.profiles WHERE id=auth.uid() FOR UPDATE; SELECT * INTO _rules FROM public.loyalty_rules WHERE id=true; IF NOT FOUND OR NOT _rules.enabled THEN RAISE EXCEPTION 'Rewards are disabled'; END IF; SELECT coalesce(sum(points),0) INTO _balance FROM public.loyalty_ledger WHERE user_id=auth.uid(); IF _points<_rules.minimum_redemption OR _points>_balance THEN RAISE EXCEPTION 'Invalid redemption amount'; END IF; _code:='IHSREWARD-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,16)); INSERT INTO public.coupons(code,discount_type,discount_value,min_order,is_active,max_uses,expires_at,owner_id) VALUES(_code,'flat',_points*_rules.point_value,_points*_rules.point_value,true,1,now()+interval '30 days',auth.uid()); INSERT INTO public.loyalty_ledger(user_id,points,reason,created_by) VALUES(auth.uid(),-_points,'Redeemed for '||_code,auth.uid()); RETURN _code; END $$;
CREATE FUNCTION public.guard_profile_program_fields() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF current_user IN ('authenticated','anon') AND NOT public.has_role(auth.uid(),'admin') THEN IF TG_OP='INSERT' THEN IF NEW.customer_group_id IS NOT NULL OR NEW.referral_code IS NOT NULL OR NEW.referred_by IS NOT NULL THEN RAISE EXCEPTION 'Program fields are managed by the store'; END IF; ELSIF NEW.customer_group_id IS DISTINCT FROM OLD.customer_group_id OR NEW.referral_code IS DISTINCT FROM OLD.referral_code OR NEW.referred_by IS DISTINCT FROM OLD.referred_by THEN RAISE EXCEPTION 'Program fields are managed by the store'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER guard_profile_program BEFORE INSERT OR UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.guard_profile_program_fields();
CREATE POLICY "Admin updates groups on profiles" ON public.profiles FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.claim_order_coupon(_order_id uuid,_user_id uuid DEFAULT NULL) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE _order public.orders; _coupon public.coupons; BEGIN SELECT * INTO _order FROM public.orders WHERE id=_order_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Order not found'; END IF; IF _order.coupon_code IS NULL THEN RETURN true; END IF; SELECT * INTO _coupon FROM public.coupons WHERE code=_order.coupon_code FOR UPDATE; IF NOT FOUND OR NOT _coupon.is_active OR (_coupon.expires_at IS NOT NULL AND _coupon.expires_at<=now()) OR (_coupon.owner_id IS NOT NULL AND _coupon.owner_id IS DISTINCT FROM _user_id) OR (_coupon.max_uses IS NOT NULL AND _coupon.used_count>=_coupon.max_uses) THEN RAISE EXCEPTION 'Coupon is unavailable or already used'; END IF; UPDATE public.coupons SET used_count=used_count+1 WHERE id=_coupon.id; RETURN true; END $$;
REVOKE ALL ON FUNCTION public.claim_order_coupon(uuid,uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.claim_order_coupon(uuid,uuid) TO service_role;